lib='''"""Reusable grid functions for ARC tasks."""
from collections import deque

def components(grid, color):
    """The connected 4-neighbor components of cells of the given color, as lists of (row, col)."""
    H, W = len(grid), len(grid[0])
    seen = [[False] * W for _ in range(H)]
    comps = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == color and not seen[i][j]:
                q = deque([(i, j)]); seen[i][j] = True; c = []
                while q:
                    y, x = q.popleft(); c.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W and grid[ny][nx] == color and not seen[ny][nx]:
                            seen[ny][nx] = True; q.append((ny, nx))
                comps.append(c)
    return comps

def bbox(cells):
    """(top, left, bottom, right) of a set/list of (row, col) cells."""
    ys = [y for y, x in cells]; xs = [x for y, x in cells]
    return min(ys), min(xs), max(ys), max(xs)

def unreachable_zeros(grid, blocked=()):
    """The zero cells not reachable from the grid border by 4-neighbor zero paths, treating the given (row, col) cells as blocked."""
    H, W = len(grid), len(grid[0])
    blocked = set(blocked)
    vis = [[False] * W for _ in range(H)]; q = deque()
    for j in range(W):
        for i in (0, H - 1):
            if grid[i][j] == 0 and (i, j) not in blocked and not vis[i][j]:
                vis[i][j] = True; q.append((i, j))
    for i in range(H):
        for j in (0, W - 1):
            if grid[i][j] == 0 and (i, j) not in blocked and not vis[i][j]:
                vis[i][j] = True; q.append((i, j))
    while q:
        y, x = q.popleft()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < H and 0 <= nx < W and grid[ny][nx] == 0 and (ny, nx) not in blocked and not vis[ny][nx]:
                vis[ny][nx] = True; q.append((ny, nx))
    return [(i, j) for i in range(H) for j in range(W) if grid[i][j] == 0 and not vis[i][j] and (i, j) not in blocked]
